for path,expected in conversion_pins.items():
 assert path not in parent['runtime_map'],f'Conversion would replace frozen ancestor: {path}'
 assert sha(root/path[6:])==expected,f'Explicit conversion dependency drift: {path}'
 mapped[path]=expected
conversion=json.loads((root/'runtime_converted_assets/conversion_binding.json').read_text())
assert conversion['kind']=='explicit_runtime_successor_conversion' and len(conversion['records'])==5
for row in conversion['records']:
 descriptor=(root/row['descriptor_path']).read_text()
 assert 'path="res://'+row['runtime_path']+'"' in descriptor,'Wrong conversion remap'
 assert 'source_file="res://'+row['source_path']+'"' in descriptor,'Wrong conversion source'
 assert sha(root/row['source_path'])==row['source_sha256'],'Original GLB changed'
r2_conversion=json.loads((root/'runtime_converted_assets/r2_conversion_binding.json').read_text())
assert r2_conversion['schema']=='runtime-gltf-successor-r2-1' and r2_conversion['editor_equivalent'] is False
for path,expected in r2_conversion['files'].items():assert sha(root/path)==expected,f'R2 conversion drift: {path}'
assert 'path="'+r2_conversion['remap']+'"' in (root/(r2_conversion['source'][6:]+'.import')).read_text()
hostile=json.loads((root/'runtime_converted_assets/hostile_textures/binding.json').read_text())
assert hostile['schema']=='hostile-runtime-textures-1' and hostile['editor_equivalent'] is False
for row in hostile['rows']:
 assert 'path="'+row['remap']+'"' in (root/row['descriptor']).read_text(), 'Wrong hostile texture remap'
